// Les Contes d'Hoffmann act-3; French public-domain source and machine-assisted English working translation.
export const hoffmannActThreeScenes = [{"number":1,"originalHeading":"SCÈNE 1","translatedHeading":"Scene 1","summary":"","sections":[{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Elle a fui, la tourterelle,","translatedTitle":"She fled, the turtledove.","participants":["ANTONIA"],"sourceStartIndex":0,"sourceLineCount":23,"turns":[{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"ANTONIA\nA Munich, chez Crespel. Une chambre bizarrement meublée. A droite, un clavecin. A gauche, canapé et fauteuil. Violons suspendus au mur. Au fond, deux portes en pan coupé. Sui le premier plan, à gauche, une fenêtre en pan coupé formant un enfoncement et donnant sur un balcon. Soleil couchant. Au fond, entre les deux portes, un grand portrait de femme accroché au mur.\nseule. Elle est assise devant le clavecin et chante.","translation":"ANTONIA\nIn Munich, at Crespel's. A strangely furnished room. To the right, a harpsichord. To the left, a sofa and an armchair. Violins hanging on the wall. At the far end, two angled doors. In the foreground, to the left, an angled window forming a recess and opening onto a balcony. Sunset. At the far end, between the two doors, a large portrait of a woman hanging on the wall.\nShe is alone. She sits in front of the harpsichord and sings.","literalText":true,"sourceStartIndex":0,"sourceLineCount":3},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"Elle a fui, la tourterelle,\nElle a fui loin de toi!","translation":"She fled, the turtledove.\nShe ran away from you!","literalText":true,"sourceStartIndex":3,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Elle s'arrête et se lève.","translation":"She stops and stands up.","literalText":true,"sourceStartIndex":5,"sourceLineCount":1},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"Ah! souvenir trop doux! image trop cruelle! ...\nHélas! à mes genoux, je l'entends, je le vois! ...","translation":"Ah! Too sweet a memory! Too cruel an image! ...\nAlas! At my knees, I hear him, I see him! ...","literalText":true,"sourceStartIndex":6,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Elle descend sur le devant de la scène.","translation":"She steps forward onto the stage.","literalText":true,"sourceStartIndex":8,"sourceLineCount":1},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"Elle a fui, la tourterelle,\nElle a fui loin de toi! ...\nMais elle est toujours fidèle\nEt te garde sa foi.\nBien-aimé, ma voix t'appelle,\nTout mon cœur est à toi.","translation":"She fled, the turtledove.\nShe ran away from you!\nBut she is still faithful\nAnd keep his faith with you.\nBeloved, my voice calls to you,\nMy whole heart belongs to you.","literalText":true,"sourceStartIndex":9,"sourceLineCount":6},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Elle se rapproche du clavecin et continue debout, en feuilletant la musique.","translation":"She approaches the harpsichord and continues standing, leafing through the music.","literalText":true,"sourceStartIndex":15,"sourceLineCount":1},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"Chère fleur qui viens d'éclore,\nPar pitié, réponds-moi,\nToi qui sais s'il m'aime encore,\nS'il me garde sa foi! ...\nBien-aimé, ma voix t'implore.\nQue ton cœur vienne à moi! ...","translation":"Dear flower that has just bloomed,\nPlease, answer me.\nYou who know if he still loves me,\nIf he keeps his faith in me! ...\nBeloved, my voice implores you.\nLet your heart come to me! ...","literalText":true,"sourceStartIndex":16,"sourceLineCount":6},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Elle se laisse tomber sur la chaise qui est devant le clavecin.","translation":"She slumps down onto the chair in front of the harpsichord.","literalText":true,"sourceStartIndex":22,"sourceLineCount":1}]}]},{"number":2,"originalHeading":"SCÈNE II","translatedHeading":"Scene 2","summary":"","sections":[{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Malheureuse enfant, fille bien-aiméeTu m'avais promis de ne plus chanter.","translatedTitle":"Unhappy child, beloved daughter, you promised me you would never sing again.","participants":["CRESPEL","ANTONIA"],"sourceStartIndex":0,"sourceLineCount":10,"turns":[{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"entrant brusquement et courant à Antonia.","translation":"entering suddenly and running to Antonia.","literalText":true,"sourceStartIndex":0,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Malheureuse enfant, fille bien-aiméeTu m'avais promis de ne plus chanter.","translation":"Unhappy child, beloved daughter, you promised me you would never sing again.","literalText":true,"sourceStartIndex":1,"sourceLineCount":1},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"Ma mère s'était en moi ranimée;\nMon cœur en chantant croyait l'écouter.","translation":"My mother had been revived within me;\nMy heart, while singing, thought it was listening to her.","literalText":true,"sourceStartIndex":2,"sourceLineCount":2},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"C'est là mon tourment. Ta mère chérie\nT'a légué sa voix, regrets superflus!\nPar toi je l'entends. Non ... non ... je t'en prie.","translation":"This is my torment. Your beloved mother\nHe bequeathed you his voice, no need for regrets!\nI mean by you. No... no... please.","literalText":true,"sourceStartIndex":4,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"tristement","translation":"sadly","literalText":true,"sourceStartIndex":7,"sourceLineCount":1},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"Votre Antonia ne chantera plus! ...","translation":"Your Antonia will sing no more!","literalText":true,"sourceStartIndex":8,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Elle sort lentement.","translation":"She comes out slowly.","literalText":true,"sourceStartIndex":9,"sourceLineCount":1}]}]},{"number":3,"originalHeading":"SCÈNE III","translatedHeading":"Scene 3","summary":"","sections":[{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Désespoir! ... Tout à l'heure encore","translatedTitle":"Despair! ... Just a little while ago","participants":["CRESPEL"],"sourceStartIndex":0,"sourceLineCount":8,"turns":[{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"seul","translation":"alone","literalText":true,"sourceStartIndex":0,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Désespoir! ... Tout à l'heure encore\nJe voyais ces taches de feu\nColorer son visage, Dieu!\nPerdrai-je l'enfant que j'adore?\nAh! cet Hoffmann ... C'est lui\nQui jeta dans son cœur ces ivresses ... J'ai fui\nJusqu'à Munich ...","translation":"Despair! ... Just a little while ago\nI could see those patches of fire\nTo color one's face, God!\nWill I lose the child I adore?\nAh! That Hoffmann... It's him\nWho cast these intoxicating thoughts into his heart... I fled\nAll the way to Munich...","literalText":true,"sourceStartIndex":1,"sourceLineCount":7}]}]},{"number":4,"originalHeading":"SCÈNE IV","translatedHeading":"Scene 4","summary":"","sections":[{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Toi, Frantz, n'ouvre à personne.","translatedTitle":"Frantz, don't open the door to anyone.","participants":["CRESPEL","FRANTZ"],"sourceStartIndex":0,"sourceLineCount":17,"turns":[{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Toi, Frantz, n'ouvre à personne.","translation":"Frantz, don't open the door to anyone.","literalText":true,"sourceStartIndex":0,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"fausse sortie","translation":"false exit","literalText":true,"sourceStartIndex":1,"sourceLineCount":1},{"speaker":"FRANTZ","speakerTranslation":"FRANTZ","original":"Vous croyez ...","translation":"You believe...","literalText":true,"sourceStartIndex":2,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Où vas-tu? ...","translation":"Where are you going?","literalText":true,"sourceStartIndex":3,"sourceLineCount":1},{"speaker":"FRANTZ","speakerTranslation":"FRANTZ","original":"Je vais voir si l'on sonne.\nComme vous avez dit ...","translation":"I'll go see if the doorbell rings.\nAs you said...","literalText":true,"sourceStartIndex":4,"sourceLineCount":2},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"J'ai dit: n'ouvre à personne!","translation":"I said: Don't open the door to anyone!","literalText":true,"sourceStartIndex":6,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Criant","translation":"Shouting","literalText":true,"sourceStartIndex":7,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"A personne! Entends-tu, cette fois?","translation":"No one! Do you hear that this time?","literalText":true,"sourceStartIndex":8,"sourceLineCount":1},{"speaker":"FRANTZ","speakerTranslation":"FRANTZ","original":"Eh! mon Dieu!\nJe ne suis pas sourd!","translation":"Oh my God!\nI'm not deaf!","literalText":true,"sourceStartIndex":9,"sourceLineCount":2},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Bien! que le diable t'emporte!","translation":"Good! May the devil take you!","literalText":true,"sourceStartIndex":11,"sourceLineCount":1},{"speaker":"FRANTZ","speakerTranslation":"FRANTZ","original":"Oui, monsieur, la clef sur la porte.","translation":"Yes sir, the key is in the door.","literalText":true,"sourceStartIndex":12,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Bélître! Ane bâté!","translation":"You scoundrel! You stupid donkey!","literalText":true,"sourceStartIndex":13,"sourceLineCount":1},{"speaker":"FRANTZ","speakerTranslation":"FRANTZ","original":"C'est convenu.","translation":"It's agreed.","literalText":true,"sourceStartIndex":14,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Morbleu!","translation":"Good heavens!","literalText":true,"sourceStartIndex":15,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Il sort vivement. Frantz va refermer la porte et redescend.","translation":"He leaves quickly. Frantz goes to close the door and goes back downstairs.","literalText":true,"sourceStartIndex":16,"sourceLineCount":1}]}]},{"number":5,"originalHeading":"SCÈNE V","translatedHeading":"Scene 5","summary":"","sections":[{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Eu bien! Quoi! toujours en colère!","translatedTitle":"Well! What! Still angry!","participants":["Stage direction"],"sourceStartIndex":0,"sourceLineCount":31,"turns":[{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Eu bien! Quoi! toujours en colère!\nBizarre! quinteux! exigeant!\nAh! l'on a du mal à lui plaire\nPour son argent ...\nJour et nuit je me mets en quatre,\nAu moindre signe je me tais,\nC'est tout comme si je chantais! ...\nEncore non, si je chantais,\nDe ses mépris il lui faudrait rabattre.\nJe chante seul quelquefois;\nMais chanter n'est pas commode!\nTra la la! Tra la la!\nCe n'est pourtant pas la voix\nQui me fait défaut, je crois...\nTra la la! Tra la la!\nNon! c'est la méthode.\nDame! on n'a pas tout en partage.\nJe chante pitoyablement;\nMais je danse agréablement,\nJe me le dis sans compliment.\nCorbleu! la danse est à mon avantage,\nC'est là mon plus grand attrait,\nEt danser n'est pas commode.\nTra la la! Tra la la!","translation":"Well! What! Still angry!\nBizarre! Quirky! Demanding!\nAh! It's hard to please him.\nFor his money...\nDay and night I go to great lengths,\nAt the slightest sign, I remain silent.\nIt's just like I'm singing!\nNo, not if I sang,\nHe would have to curb his contempt.\nI sometimes sing alone;\nBut singing is not easy!\nTra la la! Tra la la!\nHowever, that is not the voice\nWhat I'm lacking, I think...\nTra la la! Tra la la!\nNo! That's the method.\nGood heavens! We don't have everything to share.\nI sing pitifully;\nBut I dance pleasantly.\nI say that to myself without any compliment.\nGood heavens! The dance is to my advantage,\nThat's my greatest attraction,\nAnd dancing isn't easy.\nTra la la! Tra la la!","literalText":true,"sourceStartIndex":0,"sourceLineCount":24},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Il danse. Il s'arrête.","translation":"He dances. He stops.","literalText":true,"sourceStartIndex":24,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Près des femmes le jarret\nN'est pas ce qui me nuirait.\nTra la la! Tra la la!","translation":"Near the women, the hock\nThat's not what would harm me.\nTra la la! Tra la la!","literalText":true,"sourceStartIndex":25,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Il tombe.","translation":"He falls.","literalText":true,"sourceStartIndex":28,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Non! c'est la méthode.","translation":"No! That's the method.","literalText":true,"sourceStartIndex":29,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Hoffmann entre par le fond, suivi de Nicklausse.","translation":"Hoffmann enters from the back, followed by Nicklausse.","literalText":true,"sourceStartIndex":30,"sourceLineCount":1}]}]},{"number":6,"originalHeading":"SCÈNE VI","translatedHeading":"Scene 6","summary":"","sections":[{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Frantz! ... C'est ici!","translatedTitle":"Frantz! ... It's here!","participants":["HOFFMANN","FRANTZ","ANTONIA","NICKLAUSSE"],"sourceStartIndex":0,"sourceLineCount":31,"turns":[{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"paraît à la porte du fond","translation":"appears at the back door","literalText":true,"sourceStartIndex":0,"sourceLineCount":1},{"speaker":"HOFFMANN","speakerTranslation":"HOFFMANN","original":"Frantz! ... C'est ici!","translation":"Frantz! ... It's here!","literalText":true,"sourceStartIndex":1,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Il descend en scène, touchant l'épaule de Frantz","translation":"He comes down onto the stage, touching Frantz's shoulder","literalText":true,"sourceStartIndex":2,"sourceLineCount":1},{"speaker":"HOFFMANN","speakerTranslation":"HOFFMANN","original":"Debout, l'ami.","translation":"Stand up, my friend.","literalText":true,"sourceStartIndex":3,"sourceLineCount":1},{"speaker":"FRANTZ","speakerTranslation":"FRANTZ","original":"Hein! qui va là?","translation":"Hey! Who goes there?","literalText":true,"sourceStartIndex":4,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Il se relève surpris.","translation":"He gets up, surprised.","literalText":true,"sourceStartIndex":5,"sourceLineCount":1},{"speaker":"FRANTZ","speakerTranslation":"FRANTZ","original":"Monsieur Hoffmann!","translation":"Mr. Hoffmann!","literalText":true,"sourceStartIndex":6,"sourceLineCount":1},{"speaker":"HOFFMANN","speakerTranslation":"HOFFMANN","original":"Moi-même! Eh bien, Antonia?","translation":"Me! Well, Antonia?","literalText":true,"sourceStartIndex":7,"sourceLineCount":1},{"speaker":"FRANTZ","speakerTranslation":"FRANTZ","original":"Il est sorti, monsieur.","translation":"He's out, sir.","literalText":true,"sourceStartIndex":8,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"riant","translation":"laughing","literalText":true,"sourceStartIndex":9,"sourceLineCount":1},{"speaker":"HOFFMANN","speakerTranslation":"HOFFMANN","original":"Ha! ha! plus sourd encore\nQue l'an passé? ...","translation":"Ha! Ha! Even more deaf!\nWhat about last year? ...","literalText":true,"sourceStartIndex":10,"sourceLineCount":2},{"speaker":"FRANTZ","speakerTranslation":"FRANTZ","original":"Monsieur m'honore\nJe me porte bien, grâce au ciel.","translation":"Sir, I am honored\nI am doing well, thank God.","literalText":true,"sourceStartIndex":12,"sourceLineCount":2},{"speaker":"HOFFMANN","speakerTranslation":"HOFFMANN","original":"Antonia! ... Va! ... fais que je la voie!","translation":"Antonia! ... Go! ... Let me see her!","literalText":true,"sourceStartIndex":14,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"souriant","translation":"smiling","literalText":true,"sourceStartIndex":15,"sourceLineCount":1},{"speaker":"FRANTZ","speakerTranslation":"FRANTZ","original":"Très bien! ... Quelle joie\nPour monsieur Crespel!","translation":"Very good! ... What joy!\nFor Mr. Crespel!","literalText":true,"sourceStartIndex":16,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Il sort.\ns'asseyant devant le clavecin et s'accompagnant.","translation":"He leaves.\nsitting down in front of the harpsichord and accompanying himself.","literalText":true,"sourceStartIndex":18,"sourceLineCount":2},{"speaker":"HOFFMANN","speakerTranslation":"HOFFMANN","original":"C'est une chanson d'amour\nQui s'envole,\nTriste ou folle\nTour à tour! ...","translation":"It's a love song\nWho flies away,\nSad or crazy\nOne after the other!","literalText":true,"sourceStartIndex":20,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"entrant précipitamment en scène","translation":"rushing onto the scene","literalText":true,"sourceStartIndex":24,"sourceLineCount":1},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"Hoffmann! ...","translation":"Hoffmann! ...","literalText":true,"sourceStartIndex":25,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"se relevant et recevant Antonia dans ses bras","translation":"getting up and receiving Antonia in his arms","literalText":true,"sourceStartIndex":26,"sourceLineCount":1},{"speaker":"HOFFMANN","speakerTranslation":"HOFFMANN","original":"Antonia! ...","translation":"Antonia! ...","literalText":true,"sourceStartIndex":27,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"à part","translation":"apart","literalText":true,"sourceStartIndex":28,"sourceLineCount":1},{"speaker":"NICKLAUSSE","speakerTranslation":"NICKLAUSSE","original":"Je suis de trop. Bonsoir.\nIl s'esquive.","translation":"I'm in the way. Good evening.\nHe dodges it.","literalText":true,"sourceStartIndex":29,"sourceLineCount":2}]}]},{"number":7,"originalHeading":"SCÈNE VII","translatedHeading":"Scene 7","summary":"","sections":[{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Ah! je le savais bien que tu m'aimais encore!","translatedTitle":"Ah! I knew you still loved me!","participants":["ANTONIA","HOFFMANN"],"sourceStartIndex":0,"sourceLineCount":65,"turns":[{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"Ah! je le savais bien que tu m'aimais encore!","translation":"Ah! I knew you still loved me!","literalText":true,"sourceStartIndex":0,"sourceLineCount":1},{"speaker":"HOFFMANN","speakerTranslation":"HOFFMANN","original":"Mon cœur m'avait bien dit que j'étais regretté!\nMais pourquoi nous a-t-on séparés?","translation":"My heart had told me that I was missed!\nBut why were we separated?","literalText":true,"sourceStartIndex":1,"sourceLineCount":2},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"Je l'ignore.","translation":"I don't know.","literalText":true,"sourceStartIndex":3,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Ensemble","translation":"Together","literalText":true,"sourceStartIndex":4,"sourceLineCount":1},{"speaker":"HOFFMANN","speakerTranslation":"HOFFMANN","original":"Ah! j'ai le bonheur dans l'âme!\nDemain tu seras ma femme.\nHeureux époux\nL'avenir est à nous!\nA l'amour soyons fidèles!\nQue ses chaînes éternelles\nGardent nos cœurs\nDu temps même vainqueurs!","translation":"Ah! I am filled with happiness!\nTomorrow you will be my wife.\nHappy husband\nThe future is ours!\nLet us be faithful to love!\nMay his eternal chains\nThey guard our hearts\nEven the victors of time!","literalText":true,"sourceStartIndex":5,"sourceLineCount":8},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"Ah! j'ai le bonheur dans l'âme!\nDemain, je serai ta femme!\nHeureux époux,\nL'avenir est à nous!\nChaque jour, chansons nouvelles!\nTon génie ouvre ses ailes!\nMon chant vainqueur\nEst l'écho de ton cœur!","translation":"Ah! I am filled with happiness!\nTomorrow, I will be your wife!\nHappy husband,\nThe future is ours!\nNew songs every day!\nYour genius is spreading its wings!\nMy victorious song\nIt's the echo of your heart!","literalText":true,"sourceStartIndex":13,"sourceLineCount":8},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"souriant","translation":"smiling","literalText":true,"sourceStartIndex":21,"sourceLineCount":1},{"speaker":"HOFFMANN","speakerTranslation":"HOFFMANN","original":"Pourtant, ô ma fiancée,\nTe dirai-je une pensée\nQui me trouble malgré moi?\nLa musique m'inspire un peu de jalousie,\nTu l'aimes trop!","translation":"Yet, oh my fiancée,\nWill I tell you a thought\nWho is disturbing me against my will?\nMusic makes me feel a little jealous.\nYou love him too much!","literalText":true,"sourceStartIndex":22,"sourceLineCount":5},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"souriant","translation":"smiling","literalText":true,"sourceStartIndex":27,"sourceLineCount":1},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"Voyez l'étrange fantaisie!\nT'aimé-je donc pour elle, ou l'aimé-je pour toi?\nCar toi tu ne vas pas sans doute me défendre\nDe chanter, comme a fait mon père?","translation":"Behold the strange fantasy!\nDid I love you for her, or did I love her for you?\nBecause you're probably not going to defend me.\nTo sing, like my father did?","literalText":true,"sourceStartIndex":28,"sourceLineCount":4},{"speaker":"HOFFMANN","speakerTranslation":"HOFFMANN","original":"Que dis-tu?","translation":"What are you saying?","literalText":true,"sourceStartIndex":32,"sourceLineCount":1},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"Oui, mon père à présent, m'impose la vertu\nDu silence.","translation":"Yes, my father now imposes virtue upon me\nSilence.","literalText":true,"sourceStartIndex":33,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Vivement","translation":"I can't wait!","literalText":true,"sourceStartIndex":35,"sourceLineCount":1},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"Veux-tu m'entendre?","translation":"Do you want to hear me out?","literalText":true,"sourceStartIndex":36,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"à part","translation":"apart","literalText":true,"sourceStartIndex":37,"sourceLineCount":1},{"speaker":"HOFFMANN","speakerTranslation":"HOFFMANN","original":"C'est étrange! ... Est-ce donc...","translation":"That's strange! ... Is it then...","literalText":true,"sourceStartIndex":38,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"l'entraînant vers le clavecin","translation":"leading him towards the harpsichord","literalText":true,"sourceStartIndex":39,"sourceLineCount":1},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"Viens là, comme autrefois.\nÉcoute et tu verras si j'ai perdu ma voix.","translation":"Come here, like in the old days.\nListen and you'll see if I've lost my voice.","literalText":true,"sourceStartIndex":40,"sourceLineCount":2},{"speaker":"HOFFMANN","speakerTranslation":"HOFFMANN","original":"Comme ton œil s'anime et comme ta main tremble!","translation":"How your eye lights up and how your hand trembles!","literalText":true,"sourceStartIndex":42,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"le faisant s'asseoir devant le clavecin et se penchant sur son épaule.","translation":"making him sit in front of the harpsichord and leaning over his shoulder.","literalText":true,"sourceStartIndex":43,"sourceLineCount":1},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"Tiens, ce doux chant d'amour que nous chantions ensemble.","translation":"Ah, that sweet love song we used to sing together.","literalText":true,"sourceStartIndex":44,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Elle chante, accompagnée par Hoffmann.","translation":"She sings, accompanied by Hoffmann.","literalText":true,"sourceStartIndex":45,"sourceLineCount":1},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"C'est une chanson d'amour\nQui s'envole\nTriste ou folle\nTour à tour;\nC'est une chanson d'amour.\nLa rose nouvelle\nSourit au printemps.\nLas! ... combien de temps\nVivra-t-elle?","translation":"It's a love song\nWho flies away\nSad or crazy\nOne after the other;\nIt's a love song.\nThe new rose\nSmiles in the spring.\nAlas! ... how long\nWill she live?","literalText":true,"sourceStartIndex":46,"sourceLineCount":9},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Ensemble","translation":"Together","literalText":true,"sourceStartIndex":55,"sourceLineCount":1},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"C'est une chanson d'amour\nQui s'envole,\nTriste ou folle\nTour à tour.\nC'est une chanson d'amour.","translation":"It's a love song\nWho flies away,\nSad or crazy\nOne after the other.\nIt's a love song.","literalText":true,"sourceStartIndex":56,"sourceLineCount":5},{"speaker":"HOFFMANN","speakerTranslation":"HOFFMANN","original":"Un rayon de flamme\nPare ta beauté.\nVerras-tu l'été,\nFleur de l'âme?","translation":"A ray of flame\nAdorn your beauty.\nWill you see summer?\nFlower of the soul?","literalText":true,"sourceStartIndex":61,"sourceLineCount":4}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"C'est une chanson d'amour","translatedTitle":"It's a love song","participants":["HOFFMANN","ANTONIA"],"sourceStartIndex":65,"sourceLineCount":18,"turns":[{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Ensemble","translation":"Together","literalText":true,"sourceStartIndex":65,"sourceLineCount":1},{"speaker":"HOFFMANN","speakerTranslation":"HOFFMANN","original":"C'est une chanson d'amour\nQui s'envole\nTriste ou folle\nTour à tour.\nC'est une chanson d'amour.","translation":"It's a love song\nWho flies away\nSad or crazy\nOne after the other.\nIt's a love song.","literalText":true,"sourceStartIndex":66,"sourceLineCount":5},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Antonia porte la main à son cœur et semble prête à défailli.","translation":"Antonia places her hand on her heart and looks ready to faint.","literalText":true,"sourceStartIndex":71,"sourceLineCount":1},{"speaker":"HOFFMANN","speakerTranslation":"HOFFMANN","original":"Qu'as-tu donc?","translation":"What's wrong with you?","literalText":true,"sourceStartIndex":72,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"mettant la main à son cœur.","translation":"placing her hand on her heart.","literalText":true,"sourceStartIndex":73,"sourceLineCount":1},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"Rien.","translation":"Nothing.","literalText":true,"sourceStartIndex":74,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"écoutant","translation":"listening","literalText":true,"sourceStartIndex":75,"sourceLineCount":1},{"speaker":"HOFFMANN","speakerTranslation":"HOFFMANN","original":"Chut!","translation":"Shh!","literalText":true,"sourceStartIndex":76,"sourceLineCount":1},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"Ciel! mon père!\nViens! ... viens! ...","translation":"Heavens! My father!\nCome! ... come! ...","literalText":true,"sourceStartIndex":77,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Elle sort.","translation":"She goes out.","literalText":true,"sourceStartIndex":79,"sourceLineCount":1},{"speaker":"HOFFMANN","speakerTranslation":"HOFFMANN","original":"Non! je saurai le mot de ce mystère.","translation":"No! I will know the answer to this mystery.","literalText":true,"sourceStartIndex":80,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Il se cache dans l'enfoncement de la fenêtre, Crespel\nparaît.","translation":"He's hiding in the window recess, Crespel\nseems.","literalText":true,"sourceStartIndex":81,"sourceLineCount":2}]}]},{"number":8,"originalHeading":"SCÈNE VIII","translatedHeading":"Scene 8","summary":"","sections":[{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Non, rien! J'ai cru qu'Hoffmann était ici.","translatedTitle":"No, nothing! I thought Hoffmann was here.","participants":["CRESPEL","HOFFMANN","FRANTZ"],"sourceStartIndex":0,"sourceLineCount":18,"turns":[{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"regardant autour de lui","translation":"looking around him","literalText":true,"sourceStartIndex":0,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Non, rien! J'ai cru qu'Hoffmann était ici.\nPuisse-t-il être au diable!","translation":"No, nothing! I thought Hoffmann was here.\nMay he be damned!","literalText":true,"sourceStartIndex":1,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"à part","translation":"apart","literalText":true,"sourceStartIndex":3,"sourceLineCount":1},{"speaker":"HOFFMANN","speakerTranslation":"HOFFMANN","original":"Grand merci!","translation":"Thank you so much!","literalText":true,"sourceStartIndex":4,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"entrant, à Crespel","translation":"entering, at Crespel","literalText":true,"sourceStartIndex":5,"sourceLineCount":1},{"speaker":"FRANTZ","speakerTranslation":"FRANTZ","original":"Monsieur!","translation":"Sir!","literalText":true,"sourceStartIndex":6,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Quoi?","translation":"What?","literalText":true,"sourceStartIndex":7,"sourceLineCount":1},{"speaker":"FRANTZ","speakerTranslation":"FRANTZ","original":"Le docteur Miracle.","translation":"Dr. Miracle.","literalText":true,"sourceStartIndex":8,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Drôle! ... infâme!\nFerme vite la porte!","translation":"Funny! ...infamous!\nClose the door quickly!","literalText":true,"sourceStartIndex":9,"sourceLineCount":2},{"speaker":"FRANTZ","speakerTranslation":"FRANTZ","original":"Oui, monsieur, médecin ...","translation":"Yes, sir, doctor...","literalText":true,"sourceStartIndex":11,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Lui! médecin? Non, sur mon âme,\nUn fossoyeur, un assassin!\nQui me tuerait ma fille après ma femme.\nJ'entends le cliquetis de ses flacons dans l'air.\nLoin de moi qu'on le chasse.","translation":"Him! A doctor? No, on my soul,\nA gravedigger, an assassin!\nWho would kill my daughter after my wife?\nI can hear the clinking of her bottles in the air.\nI don't want him chased away.","literalText":true,"sourceStartIndex":12,"sourceLineCount":5},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Miracle paraît subitement. Frantz se sauve.","translation":"A miracle suddenly appears. Frantz escapes.","literalText":true,"sourceStartIndex":17,"sourceLineCount":1}]}]},{"number":9,"originalHeading":"SCÈNE IX","translatedHeading":"Scene 9","summary":"","sections":[{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Ha! ha! ha! ha!","translatedTitle":"Ha! Ha! Ha! Ha! Ha!","participants":["MIRACLE","CRESPEL","CRESPEL ET HOFFMANN","HOFFMANN"],"sourceStartIndex":0,"sourceLineCount":65,"turns":[{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Ha! ha! ha! ha!","translation":"Ha! Ha! Ha! Ha! Ha!","literalText":true,"sourceStartIndex":0,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Enfin!","translation":"Finally!","literalText":true,"sourceStartIndex":1,"sourceLineCount":1},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Eh bien! me voilà! c'est moi-même.\nCe bon monsieur Crespel, je l'aime!\nOù donc est-il?","translation":"Well! Here I am! It's me.\nI love that good Mr. Crespel!\nWhere is he?","literalText":true,"sourceStartIndex":2,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"l'arrêtant","translation":"arresting him","literalText":true,"sourceStartIndex":5,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Morbleu!","translation":"Good heavens!","literalText":true,"sourceStartIndex":6,"sourceLineCount":1},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Ha! ha! ha! ha!\nJe cherchais votre Antonia!\nEh bien! ce mal qu'elle hérita\nDe sa mère? Toujours en progrès? chère belle\nNous la guérirons. Menez-moi près d'elle.","translation":"Ha! Ha! Ha! Ha! Ha!\nI was looking for your Antonia!\nWell! This evil that she inherited\nFrom her mother? Still improving? Dear beautiful\nWe will heal her. Take me to her.","literalText":true,"sourceStartIndex":7,"sourceLineCount":5},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Pour l'assassiner! ... Si tu fais un pas,\nJe te jette par la fenêtre.","translation":"To assassinate him! ... If you take one step,\nI'll throw you out the window.","literalText":true,"sourceStartIndex":12,"sourceLineCount":2},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Eh! là! tout doux! Je ne veux pas\nVous déplaire.","translation":"Hey! There! Easy now! I don't want to\nTo displease you.","literalText":true,"sourceStartIndex":14,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Il avance un fauteuil.","translation":"He moves forward an armchair.","literalText":true,"sourceStartIndex":16,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Que fais-tu, traître?","translation":"What are you doing, traitor?","literalText":true,"sourceStartIndex":17,"sourceLineCount":1},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Pour conjurer le danger,\nIl faut le connaître.\nLaissez-moi l'interroger.","translation":"To avert the danger,\nYou need to know him.\nLet me question him.","literalText":true,"sourceStartIndex":18,"sourceLineCount":3},{"speaker":"CRESPEL ET HOFFMANN","speakerTranslation":"CRESPEL ET HOFFMANN","original":"L'effroi me pénètre.","translation":"Terror grips me.","literalText":true,"sourceStartIndex":21,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Ensemble\nla main étendue vers la chambre d'Antonia","translation":"Together\nher hand extended towards Antonia's room","literalText":true,"sourceStartIndex":22,"sourceLineCount":2},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"A mon pouvoir vainqueur\nCède de bonne grâce! ...\nPrès de moi, sans terreur,\nViens ici prendre place,\nViens!","translation":"To my victorious power\nGive in willingly!\nNear me, without terror,\nCome here and take a seat.\nCome!","literalText":true,"sourceStartIndex":24,"sourceLineCount":5},{"speaker":"CRESPEL ET HOFFMANN","speakerTranslation":"CRESPEL ET HOFFMANN","original":"D'épouvante et d'horreur\nTout mon être se glace.\nUne étrange terreur\nM'enchaîne à cette place,\nJ'ai peur.","translation":"Of terror and horror\nMy whole being freezes.\nA strange terror\nI am chained to this place,\nI'm scared.","literalText":true,"sourceStartIndex":29,"sourceLineCount":5},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"s'asseyant sur le tabouret du clavecin","translation":"sitting on the harpsichord stool","literalText":true,"sourceStartIndex":34,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Allons, parle, et sois bref!","translation":"Come on, speak, and be brief!","literalText":true,"sourceStartIndex":35,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Miracle continue ses passes magnétiques. La porte de la chambre d'Antonia s'ouvre lentement. Miracle indique par ses gestes qu'il prend la main d'Antonia invisible, qu'il la mène près de l'un des fauteuils et la fait s'asseoir.\nindiquant l'un des fauteuils et s'asseyant sur l'autre.","translation":"Miracle continues his magnetic passes. The door to Antonia's room slowly opens. Miracle indicates by his gestures that he takes the invisible Antonia's hand, leads her to one of the armchairs, and helps her sit down.\nindicating one of the armchairs and sitting down in the other.","literalText":true,"sourceStartIndex":36,"sourceLineCount":2},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Veuillez vous asseoir là!","translation":"Please sit down there!","literalText":true,"sourceStartIndex":38,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Je suis assis!","translation":"I am sitting down!","literalText":true,"sourceStartIndex":39,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"sans répondre à Crespel","translation":"without responding to Crespel","literalText":true,"sourceStartIndex":40,"sourceLineCount":1},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Quel âge avez-vous, je vous prie?","translation":"How old are you, please?","literalText":true,"sourceStartIndex":41,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Qui? moi?","translation":"Who? Me?","literalText":true,"sourceStartIndex":42,"sourceLineCount":1},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Je parle à votre enfant.","translation":"I'm speaking to your child.","literalText":true,"sourceStartIndex":43,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"À part","translation":"Apart","literalText":true,"sourceStartIndex":44,"sourceLineCount":1},{"speaker":"HOFFMANN","speakerTranslation":"HOFFMANN","original":"Antonia?","translation":"Antonia?","literalText":true,"sourceStartIndex":45,"sourceLineCount":1},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Quel âge? ...\nIl écoute\nVingt ans!","translation":"How old? ...\nHe listens\nTwenty years!","literalText":true,"sourceStartIndex":46,"sourceLineCount":3},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Hein?","translation":"Eh?","literalText":true,"sourceStartIndex":49,"sourceLineCount":1},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Le printemps de la vie! ...","translation":"The spring of life! ...","literalText":true,"sourceStartIndex":50,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Il fait le geste d'un homme qui tâte le pouls.","translation":"He makes the gesture of a man taking a pulse.","literalText":true,"sourceStartIndex":51,"sourceLineCount":1},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Voyons la main! ...","translation":"Let's see the hand! ...","literalText":true,"sourceStartIndex":52,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"La main? ...","translation":"The hand? ...","literalText":true,"sourceStartIndex":53,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"tirant sa montre","translation":"pulling his watch","literalText":true,"sourceStartIndex":54,"sourceLineCount":1},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Chut! Laissez-moi compter.","translation":"Shh! Let me count.","literalText":true,"sourceStartIndex":55,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"à part","translation":"apart","literalText":true,"sourceStartIndex":56,"sourceLineCount":1},{"speaker":"HOFFMANN","speakerTranslation":"HOFFMANN","original":"Dieu! ... suis-je le jouet d'un rêve? ... Est-ce un fantôme?","translation":"God! ... am I the plaything of a dream? ... Is it a ghost?","literalText":true,"sourceStartIndex":57,"sourceLineCount":1},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Le pouls est inégal et vif, mauvais symptôme!\nChantez!..","translation":"The pulse is uneven and brisk, a bad sign!\nSing!","literalText":true,"sourceStartIndex":58,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"se levant","translation":"getting up","literalText":true,"sourceStartIndex":60,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Non, non, tais-toi! ... ne la fais pas chanter!..","translation":"No, no, be quiet! ... don't make her sing!","literalText":true,"sourceStartIndex":61,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"La voix d'Antonia se fait entendre dans l'air.","translation":"Antonia's voice can be heard in the air.","literalText":true,"sourceStartIndex":62,"sourceLineCount":1},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Voyez, son front s'anime et son regard flamboie;\nElis porte la main à son cœur agité.","translation":"Look, his forehead lights up and his gaze blazes;\nElis places her hand on her troubled heart.","literalText":true,"sourceStartIndex":63,"sourceLineCount":2}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Que dit-il?","translatedTitle":"What did he say?","participants":["CRESPEL","MIRACLE","HOFFMANN"],"sourceStartIndex":65,"sourceLineCount":65,"turns":[{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Il semble suivre Antonia du geste, la porte de la chambre se referme brusquement.","translation":"He seems to be following Antonia's gesture, the bedroom door slams shut.","literalText":true,"sourceStartIndex":65,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Que dit-il?","translation":"What did he say?","literalText":true,"sourceStartIndex":66,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"se levant et remettant un des fauteuils en place.","translation":"getting up and putting one of the armchairs back in place.","literalText":true,"sourceStartIndex":67,"sourceLineCount":1},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Il serait dommage, en vérité,\nDe laisser à la mort une si belle proie!","translation":"It would be a shame, really.\nTo leave such beautiful prey to death!","literalText":true,"sourceStartIndex":68,"sourceLineCount":2},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Tais-toi! ...\nIl repousse violemment l'autre fauteuil.","translation":"Shut up! ...\nHe violently pushes the other chair away.","literalText":true,"sourceStartIndex":70,"sourceLineCount":2},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Si vous voulez accepter mon secours,\nSi vous voulez sauver ses jours,\nJ'ai là certains flacons que je tiens en réserve.","translation":"If you are willing to accept my help,\nIf you want to save his life,\nI have some bottles here that I keep in reserve.","literalText":true,"sourceStartIndex":72,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Il tire plusieurs flacons de sa poche et les fait sonner comme des castagnettes.","translation":"He takes several bottles out of his pocket and makes them ring like castanets.","literalText":true,"sourceStartIndex":75,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Tais-toi! ...","translation":"Shut up! ...","literalText":true,"sourceStartIndex":76,"sourceLineCount":1},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Dont il faudrait ...","translation":"Which would require...","literalText":true,"sourceStartIndex":77,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Tais-toi! Dieu me préserve\nD'écouter tes conseils, misérable assassin! ...","translation":"Shut up! God forbid!\nTo listen to your advice, you miserable murderer! ...","literalText":true,"sourceStartIndex":78,"sourceLineCount":2},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Dont il faudrait, chaque matin ...","translation":"Which would require, every morning...","literalText":true,"sourceStartIndex":80,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Ensemble","translation":"Together","literalText":true,"sourceStartIndex":81,"sourceLineCount":1},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Eh oui! je vous entends!\nTout à l'heure! un instant!\nDes flacons! pauvre père,\nVous en serez, j'espère\nContent!","translation":"Yes, I can hear you!\nJust a moment!\nBottles! Poor father,\nI hope you will be there.\nThrilled!","literalText":true,"sourceStartIndex":82,"sourceLineCount":5},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Va-t'en! va-t'en! va-t'en!\nHors de chez moi, Satan!\nRedoute la colère\nEt la douleur d'un père!\nVa-t'en!","translation":"Go away! Go away! Go away!\nGet out of my house, Satan!\nFear the anger\nAnd the pain of a father!\nGo away!","literalText":true,"sourceStartIndex":87,"sourceLineCount":5},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"à part","translation":"apart","literalText":true,"sourceStartIndex":92,"sourceLineCount":1},{"speaker":"HOFFMANN","speakerTranslation":"HOFFMANN","original":"A la mort qui t'attend,\nJe saurai, pauvre enfant,\nT'arracher, je l'espère!\nTu ris en vain d'un père,\nSatan!","translation":"To the death that awaits you,\nI will know, poor child,\nI hope to tear you apart!\nYou laugh in vain at a father,\nSatan!","literalText":true,"sourceStartIndex":93,"sourceLineCount":5},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"continuant toujours avec le même flegme","translation":"continuing with the same composure","literalText":true,"sourceStartIndex":98,"sourceLineCount":1},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Dont il faudrait ...","translation":"Which would require...","literalText":true,"sourceStartIndex":99,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Va-t'en!","translation":"Go away!","literalText":true,"sourceStartIndex":100,"sourceLineCount":1},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Chaque matin ...","translation":"Every morning...","literalText":true,"sourceStartIndex":101,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Va-t'en! ...","translation":"Go away!","literalText":true,"sourceStartIndex":102,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Il pousse Miracle dehors, par la porte du fond et la reforme sur lui.","translation":"He pushes Miracle out through the back door and reforms her on top of him.","literalText":true,"sourceStartIndex":103,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Ah! le voilà dehors et ma porte est fermée\nNous sommes seuls enfin,\nMa fille bien aimée!","translation":"Ah! There he is outside, and my door is closed.\nWe are finally alone.\nMy beloved daughter!","literalText":true,"sourceStartIndex":104,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"rentrant par la muraille","translation":"returning through the wall","literalText":true,"sourceStartIndex":107,"sourceLineCount":1},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Dont il faudrait chaque matin ...","translation":"Which would require every morning...","literalText":true,"sourceStartIndex":108,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Ah! misérable!\nViens! ... viens! ... Les flots puissent-ils t'engloutir\nNous verrons si le diable\nT'en fera sortir! ...","translation":"Ah! You wretch!\nCome! ... come! ... May the waves engulf you\nWe'll see if the devil\nYou'll get out of here!","literalText":true,"sourceStartIndex":109,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Ensemble","translation":"Together","literalText":true,"sourceStartIndex":113,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Va-t'en! Va-t'en! Va-t'en!\nHors de chez moi, Satan!\nRedoute la colère\nEt la douleur d'un père,\nVa-t'en!","translation":"Go away! Go away! Go away!\nGet out of my house, Satan!\nFear the anger\nAnd the pain of a father,\nGo away!","literalText":true,"sourceStartIndex":114,"sourceLineCount":5},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"à part","translation":"apart","literalText":true,"sourceStartIndex":119,"sourceLineCount":1},{"speaker":"HOFFMANN","speakerTranslation":"HOFFMANN","original":"A la mort qui t'attend,\nJe saurai, pauvre enfant,\nT'arracher, je l'espère!\nTu ris en vain d'un père,\nSatan!","translation":"To the death that awaits you,\nI will know, poor child,\nI hope to tear you apart!\nYou laugh in vain at a father,\nSatan!","literalText":true,"sourceStartIndex":120,"sourceLineCount":5},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Dont il faudrait ...","translation":"Which would require...","literalText":true,"sourceStartIndex":125,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Va-t'en!","translation":"Go away!","literalText":true,"sourceStartIndex":126,"sourceLineCount":1},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Chaque matin ...","translation":"Every morning...","literalText":true,"sourceStartIndex":127,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Va-t'en!","translation":"Go away!","literalText":true,"sourceStartIndex":128,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Il suit Miracle qui sort à reculons en faisant sonner ses flacons. Ils disparaissent ensemble.","translation":"He follows Miracle, who exits backwards, rattling his bottles. They disappear together.","literalText":true,"sourceStartIndex":129,"sourceLineCount":1}]}]},{"number":10,"originalHeading":"SCÈNE X","translatedHeading":"Scene 10","summary":"","sections":[{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Ne plus chanter! hélas! Comment obtenir d'elle","translatedTitle":"No more singing! Alas! How can I get her to sing?","participants":["HOFFMANN","ANTONIA"],"sourceStartIndex":0,"sourceLineCount":23,"turns":[{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"redescend en scène","translation":"comes back down on stage","literalText":true,"sourceStartIndex":0,"sourceLineCount":1},{"speaker":"HOFFMANN","speakerTranslation":"HOFFMANN","original":"Ne plus chanter! hélas! Comment obtenir d'elle\nUn pareil sacrifice?","translation":"No more singing! Alas! How can I get her to sing?\nSuch a sacrifice?","literalText":true,"sourceStartIndex":1,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"paraît","translation":"appears","literalText":true,"sourceStartIndex":3,"sourceLineCount":1},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"Eh bien?\nMon père, qu'a-t-il dit?","translation":"Well?\nMy father, what did he say?","literalText":true,"sourceStartIndex":4,"sourceLineCount":2},{"speaker":"HOFFMANN","speakerTranslation":"HOFFMANN","original":"Ne me demande rien,\nPlus tard tu sauras tout; une route nouvelle\nS'ouvre à nous, mon Antonia! ...\nPour y suivre mes pas, chasse de ta mémoire\nCes rêves d'avenir, de succès et de gloire\nQue ton cœur au mien confia.","translation":"Don't ask me anything.\nLater you will know everything; a new road\nIt opens up to us, my Antonia! ...\nTo follow in my footsteps, banish your memory\nThese dreams of the future, of success and glory\nThat your heart confided in mine.","literalText":true,"sourceStartIndex":6,"sourceLineCount":6},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"Mais toi-même?","translation":"But what about you?","literalText":true,"sourceStartIndex":12,"sourceLineCount":1},{"speaker":"HOFFMANN","speakerTranslation":"HOFFMANN","original":"L'amour tous les deux nous convie,\nTout ce qui n'est pas toi n'est plus rien dans ma vie.","translation":"Love invites us both,\nEverything that is not you is nothing in my life.","literalText":true,"sourceStartIndex":13,"sourceLineCount":2},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"Tiens donc! voici ma main!","translation":"Well, look at that! Here's my hand!","literalText":true,"sourceStartIndex":15,"sourceLineCount":1},{"speaker":"HOFFMANN","speakerTranslation":"HOFFMANN","original":"Ah! chère Antonia! Pourrai-je reconnaître\nCe que tu fais pour moi?","translation":"Ah! dear Antonia! Will I be able to recognize\nWhat are you doing for me?","literalText":true,"sourceStartIndex":16,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Il lui baise les mains.","translation":"He kisses her hands.","literalText":true,"sourceStartIndex":18,"sourceLineCount":1},{"speaker":"HOFFMANN","speakerTranslation":"HOFFMANN","original":"Ton père va peut-être\nRevenir, je te quitte ... à demain!","translation":"Your father might\nI'll come back, I'm leaving you now... see you tomorrow!","literalText":true,"sourceStartIndex":19,"sourceLineCount":2},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"A demain!","translation":"See you tomorrow!","literalText":true,"sourceStartIndex":21,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Hoffmann sort. Antonia le regarde s'éloigner. Après un moment, elle redescend en scène.","translation":"Hoffmann exits. Antonia watches him walk away. After a moment, she returns to the stage.","literalText":true,"sourceStartIndex":22,"sourceLineCount":1}]}]},{"number":11,"originalHeading":"SCÈNE XI","translatedHeading":"Scene 11","summary":"","sections":[{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"De mon père aisément il s'est fait le complice!","translatedTitle":"He easily became my father's accomplice!","participants":["ANTONIA","MIRACLE","LA VOIX","LE FANTOME"],"sourceStartIndex":0,"sourceLineCount":65,"turns":[{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"allant ouvrir une des portes latérales","translation":"going to open one of the side doors","literalText":true,"sourceStartIndex":0,"sourceLineCount":1},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"De mon père aisément il s'est fait le complice!\nAllons, les pleurs sont superflus,\nJe l'ai promis, je ne chanterai plus.","translation":"He easily became my father's accomplice!\nCome on, tears are unnecessary.\nI promised, I won't sing anymore.","literalText":true,"sourceStartIndex":1,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Elle se laisse tomber sur un fauteuil.\nsurgissant tout à coup derrière elle et se penchant à son oreille","translation":"She collapses into an armchair.\nsuddenly appearing behind her and leaning close to her ear","literalText":true,"sourceStartIndex":4,"sourceLineCount":2},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Tu ne chanteras plus? Sais-tu quel sacrifice\nS'impose ta jeunesse, et l'as-tu mesuré?\nLa grâce, la beauté, le talent, don sacré,\nTous ces biens que le ciel t'a livrés en partage,\nFaut-il les enfouir dans l'ombre d'un ménage?\nN'as-tu pas entendu, dans un rêve orgueilleux,\nAinsi qu'une forêt par le vent balancée,\nCe doux frémissement de la foule pressée\nQui murmure ton nom et qui te suit des yeux?\nVoilà l'ardente joie et la fête éternelle\nQue tes vingt ans en fleur sont près d'abandonner,\nPour les plaisirs bourgeois où l'on veut t'enchaîne\nEt des marmots d'enfants qui te rendront moins belle!","translation":"You won't sing anymore? Do you know what a sacrifice!\nYour youth is imposing itself, and have you considered it?\nGrace, beauty, talent, a sacred gift,\nAll these blessings that heaven has bestowed upon you,\nShould they be buried in the shadows of a household?\nHave you not heard, in a proud dream,\nLike a forest swaying in the wind,\nThis gentle rustling of the bustling crowd\nWho whispers your name and follows you with their eyes?\nThis is the ardent joy and the eternal celebration\nThat your blossoming twenties are about to give up,\nFor bourgeois pleasures where they want to chain you\nAnd a bunch of kids who will make you less beautiful!","literalText":true,"sourceStartIndex":6,"sourceLineCount":13},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"sans se retourner","translation":"without turning around","literalText":true,"sourceStartIndex":19,"sourceLineCount":1},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"Ah! quelle est cette voix qui me trouble l'esprit?\nEst-ce l'enfer qui parle ou Dieu qui m'avertit?\nNon, non, ce n'est pas là le bonheur, voix maudite,\nEt contre mon orgueil mon amour s'est armé;\nLa gloire ne vaut pas l'ombre heureuse où m'invite\nLa maison de mon bien-aimé.","translation":"Ah! What is this voice that troubles my mind?\nIs it hell speaking or God warning me?\nNo, no, that's not happiness, you cursed voice,\nAnd against my pride my love has armed itself;\nGlory is not worth the happy shade to which I am invited\nThe house of my beloved.","literalText":true,"sourceStartIndex":20,"sourceLineCount":6},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Quelles amours sont donc les vôtres?\nHoffmann te sacrifie à sa brutalité;\nIl n'aime en toi que ta beauté,\nEt pour lui, comme pour les autres,\nViendra bientôt le temps de l'infidélité! ...","translation":"So what are your loves?\nHoffmann sacrifices you to his brutality;\nHe loves only your beauty.\nAnd for him, as for the others,\nThe time for infidelity will soon come!","literalText":true,"sourceStartIndex":26,"sourceLineCount":5},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Il disparaît.\nse levant","translation":"He disappears.\ngetting up","literalText":true,"sourceStartIndex":31,"sourceLineCount":2},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"Non, ne me tente plus! ... Va-t'en,\nDémon! ... Je ne veux plus t'entendre.\nJ'ai juré d'être à lui, mon bien-aimé m'attend,\nJe ne m'appartiens plus et ne puis me reprendre;\nEt tout à l'heure encor, sur son cœur adoré,\nQuel éternel amour ne m'a-t-il pas juré; ! ...\nAh! qui me sauvera du démon, de moi-même? ...\nMa mère! ô ma mère! ... je l'aime! ...","translation":"No, don't tempt me anymore! ... Go away,\nDemon! ... I don't want to hear from you anymore.\nI swore to be his, my beloved awaits me,\nI no longer belong to myself and cannot take myself back;\nAnd just now, upon her beloved heart,\nWhat eternal love has he not sworn to me?! ...\nAh! Who will save me from the demon, from myself? ...\nMy mother! Oh, my mother! ... I love her! ...","literalText":true,"sourceStartIndex":33,"sourceLineCount":8},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Elle va tomber en pleurant près du clavecin.\nreparaît derrière Antonia","translation":"She will fall down crying near the harpsichord.\nreappears behind Antonia","literalText":true,"sourceStartIndex":41,"sourceLineCount":2},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Ta mère? ... Oses-tu l'invoquer? ...\nTa mère? Mais n'est-ce pas elle\nQui parle par ma voix, ingrate, et te rappelle\nLa splendeur de son nom que tu veux abdiquer?","translation":"Your mother? ... Do you dare invoke her? ...\nYour mother? But isn't that her?\nWho speaks through my voice, ungrateful one, and reminds you\nThe splendor of his name that you want to renounce?","literalText":true,"sourceStartIndex":43,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Le portrait s'éclaire et semble s'animer. C'est le fantôme de la mère qui apparaît à la place de la peinture.","translation":"The portrait lights up and seems to come to life. It is the ghost of the mother that appears in place of the painting.","literalText":true,"sourceStartIndex":47,"sourceLineCount":1},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Écoute! ...","translation":"Listen! ...","literalText":true,"sourceStartIndex":48,"sourceLineCount":1},{"speaker":"LA VOIX","speakerTranslation":"LA VOIX","original":"Antonia!","translation":"Antonia!","literalText":true,"sourceStartIndex":49,"sourceLineCount":1},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"Dieu! ... ma mère! ma mère.","translation":"God! ... my mother! my mother.","literalText":true,"sourceStartIndex":50,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Ensemble","translation":"Together","literalText":true,"sourceStartIndex":51,"sourceLineCount":1},{"speaker":"LE FANTOME","speakerTranslation":"LE FANTOME","original":"Cher enfant que j'appelle\nComme autrefois,\nC'est ta mère, c'est elle,\nEntends sa voix!","translation":"Dear child whom I call\nAs in the past,\nThat's your mother, that's her.\nHear his voice!","literalText":true,"sourceStartIndex":52,"sourceLineCount":4},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"Ma mère!","translation":"My mother!","literalText":true,"sourceStartIndex":56,"sourceLineCount":1},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Oui! oui! c'est sa voix, l'entends-tu?\nSa voix, meilleure conseillère,\nQui te lègue un talent que le monde a perdu!","translation":"Yes! Yes! That's his voice, can you hear it?\nHer voice, the best advisor,\nWho bequeaths to you a talent that the world has lost!","literalText":true,"sourceStartIndex":57,"sourceLineCount":3},{"speaker":"LE FANTOME","speakerTranslation":"LE FANTOME","original":"Antonia!","translation":"Antonia!","literalText":true,"sourceStartIndex":60,"sourceLineCount":1},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Écoute! Elle semble revivre\nEt le public lointain de ses bravos l'enivre!","translation":"Listen! She seems to be coming back to life.\nAnd the distant audience's applause intoxicates him!","literalText":true,"sourceStartIndex":61,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"se levant","translation":"getting up","literalText":true,"sourceStartIndex":63,"sourceLineCount":1},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"Ma mère!","translation":"My mother!","literalText":true,"sourceStartIndex":64,"sourceLineCount":1}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Antonia!","translatedTitle":"Antonia!","participants":["LE FANTOME","MIRACLE","ANTONIA","LE FANTOME."],"sourceStartIndex":65,"sourceLineCount":28,"turns":[{"speaker":"LE FANTOME","speakerTranslation":"LE FANTOME","original":"Antonia!","translation":"Antonia!","literalText":true,"sourceStartIndex":65,"sourceLineCount":1},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Reprends donc avec elle! ...","translation":"So start again with her! ...","literalText":true,"sourceStartIndex":66,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Il saisit un violon et accompagne avec une sorte de fureur.\nEnsemble","translation":"He grabs a violin and accompanies with a kind of fury.\nTogether","literalText":true,"sourceStartIndex":67,"sourceLineCount":2},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"Oui, son âme m'appelle\nComme autrefois!\nC'est ma mère, c'est elle,\nJ'entends sa voix!","translation":"Yes, his soul is calling me\nJust like in the old days!\nThat's my mother, that's her.\nI can hear his voice!","literalText":true,"sourceStartIndex":69,"sourceLineCount":4},{"speaker":"LE FANTOME","speakerTranslation":"LE FANTOME","original":"Cher enfant que j'appelle\nComme autrefois,\nC'est ta mère, c'est elle!\nEntends sa voix!","translation":"Dear child whom I call\nAs in the past,\nIt's your mother, it's her!\nHear his voice!","literalText":true,"sourceStartIndex":73,"sourceLineCount":4},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"Non! assez! ... Je succombe!","translation":"No! Enough! ... I'm giving in!","literalText":true,"sourceStartIndex":77,"sourceLineCount":1},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Encore!","translation":"Again!","literalText":true,"sourceStartIndex":78,"sourceLineCount":1},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"Je ne veux plus chanter.","translation":"I don't want to sing anymore.","literalText":true,"sourceStartIndex":79,"sourceLineCount":1},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Encore!","translation":"Again!","literalText":true,"sourceStartIndex":80,"sourceLineCount":1},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"Quelle ardeur m'entraîne et me dévore?","translation":"What passion drives and consumes me?","literalText":true,"sourceStartIndex":81,"sourceLineCount":1},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Encore! Pourquoi t'arrêter?","translation":"Again! Why stop?","literalText":true,"sourceStartIndex":82,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"haletante","translation":"panting","literalText":true,"sourceStartIndex":83,"sourceLineCount":1},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"Je cède au transport qui m'enivre!\nQuelle flamme éblouit mes yeux! ...\nUn seul moment encore à vivre,\nEt mon âme s'envole aux cieux!","translation":"I give in to the intoxicating sensation!\nWhat a flame dazzles my eyes! ...\nOnly one moment left to live.\nAnd my soul flies to heaven!","literalText":true,"sourceStartIndex":84,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Ensemble","translation":"Together","literalText":true,"sourceStartIndex":88,"sourceLineCount":1},{"speaker":"LE FANTOME.","speakerTranslation":"LE FANTOME.","original":"Cher enfant que j'appelle etc.","translation":"Dear child whom I call etc.","literalText":true,"sourceStartIndex":89,"sourceLineCount":1},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"C'est ma mère, c'est elle, etc.\nAh!","translation":"That's my mother, that's her, etc.\nAh!","literalText":true,"sourceStartIndex":90,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Elle vient tomber mourante sur le canapé. Miracle s'engloutit dans la terre en poussant un éclat de rire. La fantôme disparaît et le portrait reprend son premier aspect.","translation":"She collapses, dying, onto the sofa. Miracle burrows into the earth, bursting into laughter. The ghost vanishes, and the portrait returns to its original appearance.","literalText":true,"sourceStartIndex":92,"sourceLineCount":1}]}]},{"number":12,"originalHeading":"SCÈNE XII","translatedHeading":"Scene 12","summary":"","sections":[{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Mon enfant! ... ma fille! ... Antonia! ...","translatedTitle":"My child! ... my daughter! ... Antonia! ...","participants":["CRESPEL","ANTONIA","HOFFMANN","NICKLAUSSE","MIRACLE"],"sourceStartIndex":0,"sourceLineCount":38,"turns":[{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"accourant","translation":"running","literalText":true,"sourceStartIndex":0,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Mon enfant! ... ma fille! ... Antonia! ...","translation":"My child! ... my daughter! ... Antonia! ...","literalText":true,"sourceStartIndex":1,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"expirante","translation":"expiring","literalText":true,"sourceStartIndex":2,"sourceLineCount":1},{"speaker":"ANTONIA","speakerTranslation":"ANTONIA","original":"Mon père! ...\nÉcoutez! c'est ma mère\nQui m'appelle! ... Et lui ... de retour ...\nC'est une chanson d'amour ...\nQui s'envole ...\nTriste ou folle ...","translation":"My father! ...\nListen! That's my mother\nWho's calling me! ... And him... back again...\nIt's a love song...\nWho flies away...\nSad or crazy...","literalText":true,"sourceStartIndex":3,"sourceLineCount":6},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Elle meurt.","translation":"She dies.","literalText":true,"sourceStartIndex":9,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Non! ... un seul mot! ... un seul! ... ma fille ... parle-moi.\nMais parle donc! ... Mort exécrable! ...\nNon! ... pitié! ... grâce! ... Éloigne-toi!","translation":"No! ... just one word! ... just one! ... my daughter ... speak to me.\nSpeak up! ... Awful death! ...\nNo! ... have mercy! ... mercy! ... Go away!","literalText":true,"sourceStartIndex":10,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"entrant précipitamment","translation":"entering hastily","literalText":true,"sourceStartIndex":13,"sourceLineCount":1},{"speaker":"HOFFMANN","speakerTranslation":"HOFFMANN","original":"Pourquoi ces cris?","translation":"Why the shouting?","literalText":true,"sourceStartIndex":14,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Hoffmann! ... ah! misérable!\nC'est toi qui l'as tuée! ...","translation":"Hoffmann! ... ah! wretch!\nYou're the one who killed her!","literalText":true,"sourceStartIndex":15,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"courant à Antonia","translation":"current in Antonia","literalText":true,"sourceStartIndex":17,"sourceLineCount":1},{"speaker":"HOFFMANN","speakerTranslation":"HOFFMANN","original":"Antonia! ...","translation":"Antonia! ...","literalText":true,"sourceStartIndex":18,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"courant avec égarement","translation":"running with confusion","literalText":true,"sourceStartIndex":19,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Du sang!\nPour colorer sa joue! ... Une arme,\nUn couteau! ...","translation":"Blood!\nTo color his cheek! ... A weapon,\nA knife! ...","literalText":true,"sourceStartIndex":20,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Il saisit un couteau sur une table et va pour s'élancer sur Hoffmann.\nentrant en scène et arrêtant Crespel","translation":"He grabbed a knife from a table and went to lunge at Hoffmann.\nentering the scene and stopping Crespel","literalText":true,"sourceStartIndex":23,"sourceLineCount":2},{"speaker":"NICKLAUSSE","speakerTranslation":"NICKLAUSSE","original":"Malheureux! ...","translation":"Unfortunate man!","literalText":true,"sourceStartIndex":25,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"à Nicklausse","translation":"to Nicklausse","literalText":true,"sourceStartIndex":26,"sourceLineCount":1},{"speaker":"HOFFMANN","speakerTranslation":"HOFFMANN","original":"Vite! ... donne l'alarme! ...\nUn médecin! ... un médecin! ...","translation":"Quick! ... sound the alarm! ...\nA doctor! ... a doctor! ...","literalText":true,"sourceStartIndex":27,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"paraissant","translation":"appearing","literalText":true,"sourceStartIndex":29,"sourceLineCount":1},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Présent!","translation":"Here!","literalText":true,"sourceStartIndex":30,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Il s'approche d'Antonia et lui tâte le pouls.","translation":"He approaches Antonia and takes her pulse.","literalText":true,"sourceStartIndex":31,"sourceLineCount":1},{"speaker":"MIRACLE","speakerTranslation":"MIRACLE","original":"Morte!","translation":"Dead!","literalText":true,"sourceStartIndex":32,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"éperdu","translation":"distraught","literalText":true,"sourceStartIndex":33,"sourceLineCount":1},{"speaker":"CRESPEL","speakerTranslation":"CRESPEL","original":"Ah! Dieu, mon enfant! ma fille!","translation":"Oh God, my child! My daughter!","literalText":true,"sourceStartIndex":34,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"avec désespoir","translation":"with despair","literalText":true,"sourceStartIndex":35,"sourceLineCount":1},{"speaker":"HOFFMANN","speakerTranslation":"HOFFMANN","original":"Antonia!","translation":"Antonia!","literalText":true,"sourceStartIndex":36,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Frantz est entré le dernier et s'est agenouillé près d'Antonia.","translation":"Frantz entered last and knelt beside Antonia.","literalText":true,"sourceStartIndex":37,"sourceLineCount":1}]}]}];
